data/voice/combat.json:
{
  "about": "What fighters say or do at the turning points of a fight (kinds: engage, crit, kill, miss, dodge, hurt, fall, flee, summon, summoned, revived): by the fighter's manner (side: company) or kind of foe (role). Most are Orsino's barks (source orsino); the narrator says one now and then, never two in one exchange, and never the same one twice in a fight.",
  "kinds": [
    "engage",
    "crit",
    "kill",
    "miss",
    "dodge",
    "hurt",
    "fall",
    "flee",
    "summon",
    "summoned",
    "revived"
  ],
  "lines": [
    {
      "id": "kill.kyr.compassionate.1",
      "when": {
        "manner": "compassionate",
        "side": "company"
      },
      "text": "{Actor} stands over the body a moment, breathing hard, and does not look pleased."
    },
    {
      "id": "miss.kyr.compassionate.1",
      "when": {
        "manner": "compassionate",
        "side": "company"
      },
      "text": "{Actor} swears under {their} breath and sets {their} feet again."
    },
    {
      "id": "miss.kyr.stoic.1",
      "when": {
        "manner": "stoic",
        "side": "company"
      },
      "text": "{Actor} recovers without a word."
    },
    {
      "id": "hurt.kyr.grim.1",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} takes it, and grunts, and keeps coming."
    },
    {
      "id": "hurt.kyr.cheerful.1",
      "when": {
        "manner": [
          "cheerful",
          "jovial"
        ],
        "side": "company"
      },
      "text": "'That,' says {actor} through {their} teeth, 'is going to hurt in the morning.'"
    },
    {
      "id": "fall.kyr.company.1",
      "when": {
        "side": "company"
      },
      "text": "{Actor} goes down and does not get up."
    },
    {
      "id": "flee.kyr.beast.1",
      "when": {
        "kind": "animal"
      },
      "text": "{Actor} [break|breaks] and [run|runs], and [is|is] gone into the undergrowth."
    },
    {
      "id": "engage.kyr.beast.1",
      "when": {
        "kind": "animal"
      },
      "text": "{Actor} [come|comes] at you low and fast."
    },
    {
      "id": "summoned.orsino.generic.onSummonReceived.0",
      "text": "From the trembling earth, {actor} rises to join the fray!",
      "source": {
        "orsino": "barks:generic.onSummonReceived"
      }
    },
    {
      "id": "summoned.orsino.generic.onSummonReceived.1",
      "text": "{Actor} emerges from the shadows, ready to fight!",
      "source": {
        "orsino": "barks:generic.onSummonReceived"
      }
    },
    {
      "id": "summoned.orsino.generic.onSummonReceived.2",
      "text": "'I heed your call!', declares {actor} as they enter the battle.",
      "source": {
        "orsino": "barks:generic.onSummonReceived"
      }
    },
    {
      "id": "revived.orsino.generic.onResurrect.0",
      "text": "{Actor} gasps and returns to the fight!",
      "source": {
        "orsino": "barks:generic.onResurrect"
      }
    },
    {
      "id": "revived.orsino.generic.onResurrect.1",
      "text": "{Actor} shakes off death and stands once more!",
      "source": {
        "orsino": "barks:generic.onResurrect"
      }
    },
    {
      "id": "fall.orsino.generic.onFall.0",
      "text": "{Actor} falls to the ground, defeated.",
      "source": {
        "orsino": "barks:generic.onFall"
      }
    },
    {
      "id": "fall.orsino.generic.onFall.1",
      "text": "{Actor} collapses, unable to continue.",
      "source": {
        "orsino": "barks:generic.onFall"
      }
    },
    {
      "id": "flee.orsino.generic.onFlee.0",
      "text": "{Actor} turns and runs away!",
      "source": {
        "orsino": "barks:generic.onFlee"
      }
    },
    {
      "id": "flee.orsino.generic.onFlee.1",
      "text": "{Actor} flees the battle!",
      "source": {
        "orsino": "barks:generic.onFlee"
      }
    },
    {
      "id": "kill.orsino.personality.proud.onKill.0",
      "when": {
        "manner": "proud",
        "side": "company"
      },
      "text": "{Actor} stands over the fallen foe: ‘As expected.’",
      "source": {
        "orsino": "barks:personality.proud.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.proud.onCrit.0",
      "when": {
        "manner": "proud",
        "side": "company"
      },
      "text": "{Actor} smirks: ‘Flawless.’",
      "source": {
        "orsino": "barks:personality.proud.onCrit"
      }
    },
    {
      "id": "miss.orsino.personality.proud.onMiss.0",
      "when": {
        "manner": "proud",
        "side": "company"
      },
      "text": "{Actor} scowls in irritation.",
      "source": {
        "orsino": "barks:personality.proud.onMiss"
      }
    },
    {
      "id": "kill.orsino.personality.grim.onKill.0",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} says coldly: ‘Another one falls.’",
      "source": {
        "orsino": "barks:personality.grim.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.grim.onCrit.0",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} strikes without emotion.",
      "source": {
        "orsino": "barks:personality.grim.onCrit"
      }
    },
    {
      "id": "miss.orsino.personality.grim.onMiss.0",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} growls: ‘Damn it.’",
      "source": {
        "orsino": "barks:personality.grim.onMiss"
      }
    },
    {
      "id": "kill.orsino.personality.cheerful.onKill.0",
      "when": {
        "manner": "cheerful",
        "side": "company"
      },
      "text": "{Actor} grins: ‘Got 'em!’",
      "source": {
        "orsino": "barks:personality.cheerful.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.cheerful.onCrit.0",
      "when": {
        "manner": "cheerful",
        "side": "company"
      },
      "text": "{Actor} laughs: ‘How about that?’",
      "source": {
        "orsino": "barks:personality.cheerful.onCrit"
      }
    },
    {
      "id": "miss.orsino.personality.cheerful.onMiss.0",
      "when": {
        "manner": "cheerful",
        "side": "company"
      },
